/**
* Extracts the canonical city key from a location string.
* Prioritizes the primary city segment rather than road prefixes (e.g., "Delhi Road, Meerut" -> "meerut").
*/
function extractCanonicalCityKey(locationStr) {
	if (!locationStr) return null;
	const parts = locationStr.split(",").map((p) => normalizeCityStr(p)).filter(Boolean);
	if (parts.length === 0) return null;
	const fullNorm = normalizeCityStr(locationStr);
	if (fullNorm.includes("srinagar") && (fullNorm.includes("garhwal") || fullNorm.includes("uttarakhand") || fullNorm.includes("pauri"))) return "rudraprayag";
	if (fullNorm.includes("srinagar") && (fullNorm.includes("kashmir") || fullNorm.includes("jammu") || !fullNorm.includes("uttarakhand"))) return "srinagar";
	if (fullNorm.includes("dwarka") && fullNorm.includes("gujarat")) return "dwarka";
	for (const part of parts) for (const entry of CANONICAL_CITY_ALIASES) if (entry.patterns.some((pat) => part === pat)) return entry.key;
	const firstPart = parts[0];
	const orderedParts = (firstPart.includes("road") || firstPart.includes("gate") || firstPart.includes("bypass") || firstPart.includes("highway") || firstPart.includes("chowk") || firstPart.includes("chungi")) && parts.length > 1 ? [...parts.slice(1), firstPart] : parts;
	for (const part of orderedParts) {
		if (part.length < 3) continue;
		for (const entry of CANONICAL_CITY_ALIASES) if (entry.patterns.some((pat) => part.includes(pat) || pat.startsWith(part))) return entry.key;
	}
	return null;
}
/**
* Checks if two locations match a verified Indian highway or hill route pair
*/
function lookupVerifiedHighwayDistance(fromCity, toCity) {
	if (!fromCity || !toCity) return null;
	const keyA = extractCanonicalCityKey(fromCity);
	const keyB = extractCanonicalCityKey(toCity);
	if (!keyA || !keyB) return null;
	if (keyA === keyB) return 22;
	const pairKey = `${keyA}-${keyB}`;
	if (VERIFIED_HIGHWAY_PAIRS[pairKey] !== void 0) return VERIFIED_HIGHWAY_PAIRS[pairKey];
	return null;
}
/**
* Finds a matching CityData entry with coordinates for a location string.
* Requires at least 3 characters and avoids false 2-letter substring matches.
*/
function findMatchingIndianCity(locationStr) {
	const trimmed = (locationStr || "").trim();
	if (trimmed.length < 3) return null;
	const parts = trimmed.split(",").map((p) => normalizeCityStr(p)).filter((p) => p.length >= 3);
	if (parts.length === 0) return null;
	for (const part of parts) {
		const exact = POPULAR_INDIAN_CITIES.find((c) => {
			const cMain = normalizeCityStr(c.name.split("(")[0].split("&")[0]);
			const cFull = normalizeCityStr(c.name);
			return cMain === part || cFull === part;
		});
		if (exact) return exact;
	}
	const canonical = extractCanonicalCityKey(trimmed);
	if (canonical) {
		const byCanonical = POPULAR_INDIAN_CITIES.find((c) => {
			const cNorm = normalizeCityStr(c.name);
			return cNorm.startsWith(canonical) || cNorm.includes(canonical);
		});
		if (byCanonical) return byCanonical;
	}
	const primary = parts[0];
	if (primary.length >= 3) {
		const prefixMatch = POPULAR_INDIAN_CITIES.find((c) => {
			const cMain = normalizeCityStr(c.name.split("(")[0]);
			return cMain.startsWith(primary) || primary.includes(cMain);
		});
		if (prefixMatch) return prefixMatch;
	}
	return null;
}
function calculateTerrainHaversineKm(lat1, lon1, lat2, lon2, fromCity = "", toCity = "") {
	const R = 6371;
	const dLat = (lat2 - lat1) * (Math.PI / 180);
	const dLon = (lon2 - lon1) * (Math.PI / 180);
	const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
	const crowDistance = R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
	if (crowDistance < 1) return 5;
	const fromHill = isHillAreaToken(fromCity);
	const toHill = isHillAreaToken(toCity);
	let detourFactor = 1.28;
	if (fromHill && toHill) detourFactor = 2.042;
	else if (fromHill || toHill) detourFactor = 1.58;
	else if (crowDistance < 100) detourFactor = 1.32;
	return Math.max(4, Math.round(crowDistance * detourFactor));
}
function estimateDistanceKm(fromCity, toCity) {
	if (!fromCity || !toCity) return 150;
	if (fromCity.trim().toLowerCase() === toCity.trim().toLowerCase()) return 15;
	const verifiedKm = lookupVerifiedHighwayDistance(fromCity, toCity);
	if (verifiedKm !== null) return verifiedKm;
	const cityA = findMatchingIndianCity(fromCity);
	const cityB = findMatchingIndianCity(toCity);
	if (cityA && cityB) {
		const calc = calculateTerrainHaversineKm(cityA.lat, cityA.lon, cityB.lat, cityB.lon, fromCity, toCity);
		return Math.max(4, calc);
	}
	return 150;
}
