function extractRegionalCanonicalCity(locationStr) {
	if (!locationStr) return null;
	const parts = locationStr.split(",").map((p) => p.toLowerCase().replace(/[^a-z]/g, "")).filter(Boolean);
	if (parts.length === 0) return null;
	for (const part of parts) for (const entry of REGIONAL_CITY_TOKEN_MAP) if (entry.tokens.some((tok) => part === tok)) return entry.key;
	for (const part of parts) {
		if (part.length < 3) continue;
		for (const entry of REGIONAL_CITY_TOKEN_MAP) if (entry.tokens.some((tok) => part.includes(tok))) return entry.key;
	}
	return null;
}
function lookupBiharJharkhandFixedRoute(pickupCity, dropCity) {
	if (!pickupCity || !dropCity) return null;
	const cityA = extractRegionalCanonicalCity(pickupCity);
	const cityB = extractRegionalCanonicalCity(dropCity);
	if (!cityA || !cityB || cityA === cityB) return null;
	const directKey = `${cityA}-${cityB}`;
	if (BIHAR_JHARKHAND_FIXED_ROUTES[directKey]) return BIHAR_JHARKHAND_FIXED_ROUTES[directKey];
	const reverseKey = `${cityB}-${cityA}`;
	if (BIHAR_JHARKHAND_FIXED_ROUTES[reverseKey]) return BIHAR_JHARKHAND_FIXED_ROUTES[reverseKey];
	return null;
}
function isBiharJharkhandRegionalTrip(pickupCity, dropCity, originState, destState) {
	if (originState === "Bihar" || originState === "Jharkhand" || destState === "Bihar" || destState === "Jharkhand") return true;
	return Boolean(extractRegionalCanonicalCity(pickupCity) || extractRegionalCanonicalCity(dropCity));
}
function normalizeRouteToken(str) {
	return (str || "").toLowerCase().replace(/[^a-z]/g, "");
}
function isLocationInHillArea(locationStr) {
	if (!locationStr) return false;
	const norm = normalizeRouteToken(locationStr);
	if (!norm) return false;
	return HILL_STATION_KEYWORDS.some((kw) => norm.includes(kw));
}
function isLocationFoothillGateway(locationStr) {
	if (!locationStr) return false;
	const norm = normalizeRouteToken(locationStr);
	if (!norm) return false;
	return FOOTHILL_GATEWAY_KEYWORDS.some((kw) => norm.includes(kw));
}
function computeHillTerrainPricing(tripType, pickupCity, dropCity) {
	const pickupIsHill = isLocationInHillArea(pickupCity);
	const dropIsHill = tripType === "local" ? pickupIsHill : isLocationInHillArea(dropCity);
	const pickupIsGateway = isLocationFoothillGateway(pickupCity);
	const dropIsGateway = tripType === "local" ? pickupIsGateway : isLocationFoothillGateway(dropCity);
	if (!(pickupIsHill || dropIsHill)) {
		if (pickupIsGateway || dropIsGateway) return {
			isHillRoute: false,
			pickupIsHill: false,
			dropIsHill: false,
			hillTier: "foothill_gateway",
			hillRateMultiplier: 1,
			hillTierLabel: "Foothill Gateway Corridor"
		};
		return {
			isHillRoute: false,
			pickupIsHill: false,
			dropIsHill: false,
			hillTier: "none",
			hillRateMultiplier: 1,
			hillTierLabel: ""
		};
	}
	if (pickupIsHill && dropIsHill && tripType !== "local") return {
		isHillRoute: true,
		pickupIsHill: true,
		dropIsHill: true,
		hillTier: "both_hills",
		hillRateMultiplier: 1,
		hillTierLabel: "Hill Area Pickup (₹16/km)"
	};
	return {
		isHillRoute: true,
		pickupIsHill,
		dropIsHill,
		hillTier: "one_end_hill",
		hillRateMultiplier: 1,
		hillTierLabel: pickupIsHill ? "Hill Area Pickup (₹16/km)" : "Hill Area Drop (₹13/km)"
	};
}
function detectLocationState(locationStr, fallbackState = "Delhi") {
	if (!locationStr) return fallbackState;
	const norm = normalizeRouteToken(locationStr);
	for (const entry of CITY_STATE_KEYWORDS) for (const kw of entry.keywords) if (norm.includes(kw)) return entry.state;
	return fallbackState;
}
