function haversineDistanceKmPoints(lat1, lng1, lat2, lng2) {
	const R = 6371;
	const dLat = (lat2 - lat1) * Math.PI / 180;
	const dLng = (lng2 - lng1) * Math.PI / 180;
	const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
	return 2 * R * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
function pointToSegmentDistanceKm(pLat, pLng, aLat, aLng, bLat, bLng) {
	const dx = bLng - aLng;
	const dy = bLat - aLat;
	if (dx === 0 && dy === 0) return haversineDistanceKmPoints(pLat, pLng, aLat, aLng);
	const t = Math.max(0, Math.min(1, ((pLng - aLng) * dx + (pLat - aLat) * dy) / (dx * dx + dy * dy)));
	const projLng = aLng + t * dx;
	return haversineDistanceKmPoints(pLat, pLng, aLat + t * dy, projLng);
}
